module lex_string (\n    input [5:0] n,\n    input [2:0] k,\n    output reg valid,\n    output reg [511:0] string_data\n);\n\n    integer i;\n\n    always @(*) begin\n        if (k < 3'd1 || k > 3'd8 || n < k || (k == 3'd1 && n != 6'd1)) begin\n            valid = 1'b0;\n            string_data = 512'd0;\n        end else begin\n            valid = 1'b1;\n            string_data = 512'd0;\n            \n            for (i = 0; i < 64; i = i + 1) begin\n                if (i < n) begin\n                    if (i < (n - {3'b0, k} + 6'd2)) begin\n                        string_data[8*i +: 8] = (i[0] == 1'b0) ? 8'h61 : 8'h62;\n                    end else begin\n                        string_data[8*i +: 8] = 8'h63 + (i - (n - {3'b0, k} + 6'd2));\n                    end\n                end\n            end\n        end\n    end\n\nendmodule